package com.zc.agent.registry.modules.tool.service;import com.fasterxml.jackson.databind.*;import com.zc.agent.registry.common.exception.BusinessException;import com.zc.agent.registry.modules.tool.dto.ToolContractRequests.*;import com.zc.agent.registry.security.SecurityUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
/** Tool 输入 Contract 版本、样例回归与发布治理。 */@Service public class ToolContractService{private final JdbcTemplate jdbc;private final ObjectMapper mapper;public ToolContractService(JdbcTemplate j,ObjectMapper m){jdbc=j;mapper=m;}public List<Map<String,Object>> list(Long toolId){return jdbc.queryForList("SELECT c.*,COUNT(t.id) test_case_count FROM tool_input_contracts c LEFT JOIN tool_contract_test_cases t ON t.contract_id=c.id WHERE c.tool_id=? GROUP BY c.id ORDER BY c.created_at DESC",toolId);}public List<Map<String,Object>> cases(Long id){return jdbc.queryForList("SELECT * FROM tool_contract_test_cases WHERE contract_id=? ORDER BY id",id);}
 @Transactional public void create(Long toolId,ContractRequest r,SecurityUser u){validate(r);jdbc.update("INSERT INTO tool_input_contracts(tool_id,contract_version,input_schema,max_payload_chars,sensitive_paths,compatibility,status,release_notes,created_by) VALUES(?,?,CAST(? AS JSONB),?,CAST(? AS JSONB),?,?,?,?)",toolId,r.contractVersion(),r.inputSchema().toString(),r.maxPayloadChars(),json(r.sensitivePaths()),r.compatibility(),r.status(),r.releaseNotes(),u.userId());}
 public void addCase(Long id,TestCaseRequest r,SecurityUser u){jdbc.update("INSERT INTO tool_contract_test_cases(contract_id,case_name,input_payload,expected_valid,error_contains,status,created_by) VALUES(?,?,CAST(? AS JSONB),?,?,?,?)",id,r.caseName(),r.inputPayload().toString(),r.expectedValid(),r.errorContains(),r.status(),u.userId());}
 @Transactional public Map<String,Object> publish(Long id){Map<String,Object> c=jdbc.queryForMap("SELECT * FROM tool_input_contracts WHERE id=?",id);List<Map<String,Object>> tests=cases(id);if(tests.isEmpty())throw new BusinessException("Tool Contract 至少需要一个回归用例才能发布");List<Map<String,Object>> results=new ArrayList<>();int failures=0;JsonNode schema=parse(c.get("input_schema"));for(Map<String,Object> t:tests){JsonNode input=parse(t.get("input_payload"));List<String>errors=validateInput(input,schema);boolean actual=errors.isEmpty(),expected=(Boolean)t.get("expected_valid");boolean passed=actual==expected;if(!passed)failures++;results.add(Map.of("caseName",t.get("case_name"),"passed",passed,"actualValid",actual,"errors",errors));}if(failures>0)throw new BusinessException("Tool Contract 回归失败，失败用例数: "+failures);jdbc.update("UPDATE tool_input_contracts SET status='deprecated' WHERE tool_id=? AND status='published'",c.get("tool_id"));jdbc.update("UPDATE tool_input_contracts SET status='published' WHERE id=?",id);return Map.of("passed",true,"caseCount",tests.size(),"results",results);}
 private List<String>validateInput(JsonNode d,JsonNode s){List<String>e=new ArrayList<>();if(s.path("required").isArray())s.path("required").forEach(v->{if(!d.has(v.asText()))e.add("缺少字段 "+v.asText());});if("object".equals(s.path("type").asText())&&!d.isObject())e.add("输入必须为 object");return e;}private void validate(ContractRequest r){if(!Set.of("compatible","breaking","unknown").contains(r.compatibility()))throw new BusinessException("不支持的兼容性");if(!Set.of("draft","published","deprecated","retired").contains(r.status()))throw new BusinessException("不支持的契约状态");}private JsonNode parse(Object v){try{return v instanceof JsonNode n?n:mapper.readTree(String.valueOf(v));}catch(Exception e){return mapper.createObjectNode();}}private String json(Object v){try{return mapper.writeValueAsString(v==null?List.of():v);}catch(Exception e){return "[]";}}}
